const items = $input.all();
const boards = items[0]?.json?.data?.boards || [];
const board = boards[0] || {};
const boardItems = board.items_page?.items || [];
const boardName = board.name || 'Unknown Board';

return boardItems.map(bItem => {
  const columns = {};
  (bItem.column_values || []).forEach(col => {
    columns[col.title || col.id] = col.text || '';
  });
  return {
    json: {
      boardName: boardName,
      itemId: bItem.id || '',
      itemName: bItem.name || '',
      group: bItem.group?.title || '',
      createdAt: bItem.created_at || '',
      updatedAt: bItem.updated_at || '',
      exportDate: new Date().toISOString(),
      ...columns
    }
  };
});

